SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0710000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 71, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "71", "printedPageNumber": 71, "pdfPageNumber": 454, "sequenceIndex": 61, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0710100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—IX", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0710200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—X", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "b0710300-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—XI", "sourceIdentifier": null, "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0710000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (a)—Quotations from the Qur''an", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710100-0000-4000-8000-000000000001", "structuralNodeId": "b0710100-0000-4000-8000-000000000001", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—IX", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710200-0000-4000-8000-000000000001", "structuralNodeId": "b0710100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَعِبَادُ الرَّحْمَٰنِ الَّذِينَ يَمْشُونَ عَلَى الْأَرْضِ هَوْنًا وَإِذَا خَاطَبَهُمُ الْجَاهِلُونَ قَالُوا سَلَامًا ۝ وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710300-0000-4000-8000-000000000001", "structuralNodeId": "b0710100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"The (faithful) slaves of Rahmaan (the Beneficent) are they who walk upon the earth modestly and when the foolish ever address them, they answer: Peace; and who spend the night before their Lord, prostrate and standing.\" (XXV: 63–64)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710400-0000-4000-8000-000000000001", "structuralNodeId": "b0710100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "After describing a few more qualities of His faithful slaves, Allah says in the same context:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710500-0000-4000-8000-000000000001", "structuralNodeId": "b0710100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "أُولَٰئِكَ يُجْزَوْنَ الْغُرْفَةَ بِمَا صَبَرُوا وَيُلَقَّوْنَ فِيهَا تَحِيَّةً وَسَلَامًا ۝ خَالِدِينَ فِيهَا حَسُنَتْ مُسْتَقَرًّا وَمُقَامًا", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710600-0000-4000-8000-000000000001", "structuralNodeId": "b0710100-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"They will be awarded the high place for as much as they were steadfast, and they will meet therein with welcome and the word of peace. Abiding there for ever. Happy is it as abode and station.\" (XXV: 75–76)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710700-0000-4000-8000-000000000001", "structuralNodeId": "b0710200-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—X", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710800-0000-4000-8000-000000000001", "structuralNodeId": "b0710200-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "تَتَجَافَىٰ جُنُوبُهُمْ عَنِ الْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ ۝ فَلَا تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ جَزَاءً بِمَا كَانُوا يَعْمَلُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710900-0000-4000-8000-000000000001", "structuralNodeId": "b0710200-0000-4000-8000-000000000001", "sequenceIndex": 9, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"The believers in our revelations are those who forsake their beds, to cry unto their Lord in fear and hope, and spend of what We have bestowed on them. No soul knoweth what is kept hid for them of joy, as a reward for what they used to do.\" (XXXII: 16–17)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0711000-0000-4000-8000-000000000001", "structuralNodeId": "b0710300-0000-4000-8000-000000000001", "sequenceIndex": 10, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—XI", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0711100-0000-4000-8000-000000000001", "structuralNodeId": "b0710300-0000-4000-8000-000000000001", "sequenceIndex": 11, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَعُيُونٍ ۝ آخِذِينَ مَا آتَاهُمْ رَبُّهُمْ إِنَّهُمْ كَانُوا قَبْلَ ذَٰلِكَ مُحْسِنِينَ ۝ كَانُوا قَلِيلًا مِنَ اللَّيْلِ مَا يَهْجَعُونَ ۝ وَبِالْأَسْحَارِ هُمْ يَسْتَغْفِرُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0711200-0000-4000-8000-000000000001", "structuralNodeId": "b0710300-0000-4000-8000-000000000001", "sequenceIndex": 12, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Lo! those who keep from evil will dwell amid gardens and water-springs, taking to that which their Lord", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}]}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0720000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 72, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "72", "printedPageNumber": 72, "pdfPageNumber": 455, "sequenceIndex": 62, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0720100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—XII", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0720200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—XIII", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0720000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "giveth them; for Lo! aforetime they were doers of good. They used to sleep but little in the night. And ere the dawning of each day, would seek forgiveness.\" (LI: 15–18)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720200-0000-4000-8000-000000000001", "structuralNodeId": "b0720100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—XII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720300-0000-4000-8000-000000000001", "structuralNodeId": "b0720100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "أَمَّنْ هُوَ قَانِتٌ آنَاءَ اللَّيْلِ سَاجِدًا وَقَائِمًا يَحْذَرُ الْآخِرَةَ وَيَرْجُو رَحْمَةَ رَبِّهِ قُلْ هَلْ يَسْتَوِي الَّذِينَ يَعْلَمُونَ وَالَّذِينَ لَا يَعْلَمُونَ إِنَّمَا يَتَذَكَّرُ أُولُو الْأَلْبَابِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720400-0000-4000-8000-000000000001", "structuralNodeId": "b0720100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Is he who worships devoutly in the hours of the night, prostrate or standing, afraid of the Hereafter and hoping for the mercy of his Lord (to be counted equal with a disbeliever)? Say (unto them, O Muhammad) (Sallallaho alaihe wasallam): \"Can those who know be equal with those who know not? But only men of understanding will pay heed.\" (XXXIX: 9)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720500-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—XIII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720600-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَالْمَلَائِكَةُ يَدْخُلُونَ عَلَيْهِمْ مِنْ كُلِّ بَابٍ ۝ سَلَامٌ عَلَيْكُمْ بِمَا صَبَرْتُمْ فَنِعْمَ عُقْبَى الدَّارِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720700-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "And angels would be entering through every door proclaiming: \"Peace be upon you, as a reward for your perseverance on religious practices.\" Thus how splendid would be their end! (XIII: 22–23).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720800-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "إِنَّ الْإِنْسَانَ خُلِقَ هَلُوعًا ۝ إِذَا مَسَّهُ الشَّرُّ جَزُوعًا ۝ وَإِذَا مَسَّهُ الْخَيْرُ مَنُوعًا ۝ إِلَّا الْمُصَلِّينَ ۝ الَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ دَائِمُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720900-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 9, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Lo! man was created very impatient. Fretful when evil befalleth him. And niggardly when good befalleth him, save the worshippers who are constant at their salaat.\" (LXX: 19–23)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0721000-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 10, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "After giving some more qualities of these blessed people, Allah says in the same context:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0721100-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 11, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَالَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ ۝ أُولَٰئِكَ فِي جَنَّاتٍ مُكْرَمُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}]}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0730000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 73, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "73", "printedPageNumber": 73, "pdfPageNumber": 456, "sequenceIndex": 63, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0730000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (a)—Quotations from the Qur''an", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"And those who guard their salaat. These will dwell in gardens, honoured.\" (LXX: 34–35).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Besides the quotations given above, there are many verses of the Holy Qur''an enjoining salaat and exalting and extolling those who say their salaat properly. Salaat is indeed a great boon. That is why Muhammad (Sallallaho alaihe wasallam) has called it ''the comfort of my eyes'', and Ibrahim (Alayhis salaam) prayed to Allah,", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِنْ ذُرِّيَّتِي رَبَّنَا وَتَقَبَّلْ دُعَاءِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"My Lord! make me to establish Salaat, and some of my posterity (also); our Lord! and accept the prayer.\" (XIV: 40)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730500-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Here the eminent Prophet of Allah, whom Allah has called ''Khaleel'', is asking Allah to make him say his salaat properly and regularly. The Glorious Allah Himself is ordering His beloved Prophet (Sallallaho alaihe wasallam) thus:—", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730600-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَأْمُرْ أَهْلَكَ بِالصَّلَاةِ وَاصْطَبِرْ عَلَيْهَا لَا نَسْأَلُكَ رِزْقًا نَحْنُ نَرْزُقُكَ وَالْعَاقِبَةُ لِلتَّقْوَىٰ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730700-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 7, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"And enjoin salaat upon the people and be constant therein. We ask not of thee a provision. We provide for thee. And the Hereafter is for righteousness.\" (XX: 132).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730800-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 8, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is said in a hadith that whenever the housefolk of the Prophet (Sallallaho alaihe wasallam) were hard-pressed in any way, he enjoined salaat on them and used to recite this verse. All the Prophets of Allah (peace be upon them) are reported to have engaged themselves in salaat whenever they had any difficulty. But, alas! we are so unmindful and indifferent about salaat that, in spite of all that we proclaim about Islaam and Islamic practices, we pay no attention to it. But on the contrary, if anybody stands up to invite us and to draw our attention towards it, we cut jokes and sneer at him and oppose him, thereby harming none else but ourselves.\n\nEven those who offer the salaat, often perform it in such a way that it will not be wrong to call it a mockery of salaat, as it lacks the proper observation of its requisites", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}]}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0740000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 74, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "74", "printedPageNumber": 74, "pdfPageNumber": 457, "sequenceIndex": 64, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0740000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 74"}, {"id": "f0740100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "and also the devotion and submission obligatory therein. The practical example of the Holy Prophet (Sallallaho alaihe wasallam), as also the practices of his illustrious companions, should be the guiding factor in our lives. I have collected the stories about the salaat of the companions in a separate book, named \"Stories of Sahabah\"; and I need not repeat them here. However, I am giving stories from the lives of a few pious persons in the following pages. The practices and the sayings of the Holy Prophet (Sallallaho alaihe wasallam) about this subject would appear in Chapter III.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 74"}]}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0750000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 75, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "75", "printedPageNumber": 75, "pdfPageNumber": 458, "sequenceIndex": 65, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0750100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "CHAPTER II", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0750200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "A FEW STORIES FROM THE LIVES OF THE PIOUS", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "b0750300-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—I", "sourceIdentifier": null, "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}, {"id": "b0750400-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—II", "sourceIdentifier": null, "title": null, "sequenceIndex": 3, "startPageId": null, "endPageId": null}, {"id": "b0750500-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Story—III", "sourceIdentifier": null, "title": null, "sequenceIndex": 4, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0750000-0000-4000-8000-000000000001", "structuralNodeId": "b0750100-0000-4000-8000-000000000001", "sequenceIndex": 0, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "CHAPTER II", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 75"}, {"id": "f0750100-0000-4000-8000-000000000001", "structuralNodeId": "b0750200-0000-4000-8000-000000000001", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "A FEW STORIES FROM THE LIVES OF THE PIOUS", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 75"}, {"id": "f0750200-0000-4000-8000-000000000001", "structuralNodeId": "b0750300-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—I", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 75"}, {"id": "f0750300-0000-4000-8000-000000000001", "structuralNodeId": "b0750300-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Shaikh Abdul Waahid (Rahmatullah alaih) says, \"One day I was so much overpowered by sleep that I went to bed before finishing my Zikr for the night. I saw in my dream a most beautiful girl dressed in green silk. All parts of her body and even her shoes were engaged in Zikr. She said to me ''Aspire to possess me; I love you.'' And then she recited a few couplets depicting the eagerness of a lover. When I woke up from the dream, I vowed not to sleep any more during the night. It is reported that for full forty years he never slept at night, and said Ishaa and Fajr salaats with the same wudhu.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 75"}, {"id": "f0750400-0000-4000-8000-000000000001", "structuralNodeId": "b0750400-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—II", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 75"}, {"id": "f0750500-0000-4000-8000-000000000001", "structuralNodeId": "b0750400-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Shaikh Mazhar Sa''di (Rahmatullah alaih), the famous pious man, kept weeping for sixty years in love and eagerness for Allah. One night he saw in a dream a few damsels by the side of pearl trees with gold branches, on the bank of the brook brimming with fluid musk, pure and fragrant. The girls were hymning the glory of Allah. He asked their identity. In reply they recited two couplets, which meant, \"We have been created by the Sustainer of mankind and Lord of Muhammad (Sallallaho alaihe wasallam) for those people who keep standing before Allah all night long and hymning in supplication to Him.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 75"}, {"id": "f0750600-0000-4000-8000-000000000001", "structuralNodeId": "b0750500-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Story—III", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 75"}, {"id": "f0750700-0000-4000-8000-000000000001", "structuralNodeId": "b0750500-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Abu Bakr Dharir (Rahmatullah alaih) says, \"There lived a young slave with me. He fasted all day and stood in Tahajjud all night long. One day he came to me and related: ''Last night against my usual practice I went to sleep. I saw in my dream that the wall of the Mihraab was cracked, and from the crevice appeared a few damsels. One of them was very ugly. I asked one of the pretty damsels", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 75"}]}'::jsonb);